function tbutton1()
  if t1 ~= nil then
    target = t1
    cecho("<white>Target set to <firebrick>" .. target .. "<white>.\n\n")
    TargetInput:echo("<center>" .. target)
    table.save(PkgPath .. "vt.lua", vt)
  else
    cecho(
      "<white>You do not have a target assigned to F1. Use the 't1' command to add an alternate target.\n\n"
    )
  end
end

function abutton2()
  if a2 ~= nil then
    action = a2
    cecho("<white>Action set to <steel_blue>" .. action .. "<white>.\n\n")
    ActionInput:echo("<center>" .. action)
    table.save(PkgPath .. "vt.lua", vt)
  else
    cecho(
      "<white>You do not have an action assigned to F2. Use the 'a2' command to add an alternate action.\n\n"
    )
  end
end

function albutton3()
  if ally ~= nil then
    ally = al3
    cecho("<white>Ally set to <steel_blue>" .. action .. "<white>.\n\n")
    ActionInput:echo("<center>" .. action)
    table.save(PkgPath .. "vt.lua", vt)
  else
    cecho(
      "<white>You do not have an ally assigned to F3. Use the 'al3' command to add an alternate action.\n\n"
    )
  end
end

